-- Pagos con la tarjeta Visa Business de Galicia (resúmenes 23/07 y 20/08) cruzados con compras «a reconstruir».
-- Cada consumo cruza con UNA factura impaga por importe exacto (±1 centavo) y fecha (el consumo va de 3 días antes
-- a 15 después de la factura). Una OP por factura, forma «tarjeta», cuenta de origen «Tarjeta Visa» (tesorería 20),
-- con fecha del consumo. Si el cupón difiere 1 centavo de la factura se paga el saldo de la factura y queda anotado.
-- Fuente: ~/Desktop/CADINC-documentos/Banco/Galicia/Tarjeta/.
do $m$
declare
  u  uuid := 'a7d0ea6b-0bec-4ac0-bfc8-ef6262743dd8';
  d  jsonb := '[{"f": 87, "fecha": "2026-07-01", "monto": 98300.0, "ref": "Visa Business Galicia · resumen 23/07/2026 · consumo 01/07 MERPAGO*SUREF cupón 450571 · tarjeta 9615", "dif": 0.0}, {"f": 107, "fecha": "2026-07-01", "monto": 40834.73, "ref": "Visa Business Galicia · resumen 23/07/2026 · consumo 01/07 MERPAGO*SMARTONE cupón 906059 · tarjeta 9615", "dif": 0.0}, {"f": 95, "fecha": "2026-07-07", "monto": 3976.6, "ref": "Visa Business Galicia · resumen 23/07/2026 · consumo 07/07 AUTOPISTA DEL OE 803371719194901 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 155, "fecha": "2026-07-14", "monto": 561313.65, "ref": "Visa Business Galicia · resumen 23/07/2026 · consumo 14/07 MERPAGO*MERCADOLIBRE cupón 322114 · tarjeta 9615", "dif": 0.01}, {"f": 121, "fecha": "2026-07-07", "monto": 354800.0, "ref": "Visa Business Galicia · resumen 23/07/2026 · consumo 07/07 MERPAGO*FBSERVICIOS cupón 089012 · tarjeta 7499", "dif": 0.0}, {"f": 370, "fecha": "2026-07-31", "monto": 8500.0, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 31/07 NIC ARGENTINA cupón 001547 · tarjeta 6498", "dif": 0.0}, {"f": 312, "fecha": "2026-07-26", "monto": 529000.0, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 26/07 MERPAGO*TODOSEGURIDAD cupón 444956 · tarjeta 9615", "dif": 0.0}, {"f": 335, "fecha": "2026-07-30", "monto": 50349.06, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 30/07 MERPAGO*HAMC cupón 369705 · tarjeta 9615", "dif": -0.01}, {"f": 340, "fecha": "2026-07-30", "monto": 9990.0, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 30/07 MERPAGO*MELI cupón 498392 · tarjeta 9615", "dif": 0.0}, {"f": 284, "fecha": "2026-07-31", "monto": 1043.92, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 31/07 PEAJE ROS-VIC CA 000000349522676 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 357, "fecha": "2026-08-03", "monto": 4707.32, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 03/08 AUTOVIA DEL MERC 908033717191949 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 397, "fecha": "2026-08-04", "monto": 287902.1, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 04/08 MERPAGO*BAIRESROCKS cupón 083141 · tarjeta 9615", "dif": 0.01}, {"f": 395, "fecha": "2026-08-04", "monto": 196000.0, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 04/08 MERPAGO*CENTRALFRENOS cupón 886615 · tarjeta 9615", "dif": 0.0}, {"f": 237, "fecha": "2026-08-05", "monto": 4200.0, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 05/08 AUTOPISTA PROVIN 908033717191949 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 364, "fecha": "2026-08-07", "monto": 11308.88, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 07/08 CAMINOS DE LAS S 000000003967101 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 587, "fecha": "2026-08-18", "monto": 178329.15, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 18/08 MERPAGO*CENTRALDEHERR cupón 585471 · tarjeta 9615", "dif": 0.0}, {"f": 533, "fecha": "2026-08-18", "monto": 14121.97, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 18/08 AUTOVIA DEL MERC 908033717191949 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 500, "fecha": "2026-08-19", "monto": 121474.32, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 19/08 PEAJE ROS-VIC CA 000000354647817 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 530, "fecha": "2026-08-19", "monto": 1548.82, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 19/08 RUTAS SUR ATLANT 000000354647817 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 534, "fecha": "2026-08-20", "monto": 1988.3, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 20/08 AUTOPISTAS DEL S 803371719194901 cupón 000001 · tarjeta 9615", "dif": 0.0}, {"f": 320, "fecha": "2026-07-28", "monto": 93000.0, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 28/07 MERPAGO*GRUPOPROTEC cupón 129378 · tarjeta 7499", "dif": 0.0}, {"f": 405, "fecha": "2026-08-04", "monto": 309999.0, "ref": "Visa Business Galicia · resumen 20/08/2026 · consumo 04/08 MERPAGO*MERCADOLIBRE cupón 770628 · tarjeta 7499", "dif": 0.0}, {"f": 111, "fecha": "2026-06-27", "monto": 522999.99, "ref": "Visa Business Galicia · resumen 23/07/2026 · consumo 27/06 MERPAGO*TODOSEGURIDAD cupón 662664 · tarjeta 9615", "dif": 0.01}]'::jsonb;
  e  jsonb;
  v_prov bigint;
begin
  for e in select * from jsonb_array_elements(d) loop
    select proveedor_id into v_prov from public.pagos_facturas where id = (e->>'f')::bigint;
    perform public.pagos_reconstruir_orden(v_prov,
      jsonb_build_object('fecha', e->>'fecha', 'forma_pago', 'tarjeta', 'monto_pagado', (e->>'monto')::numeric,
        'cuenta_origen_id', 20, 'referencia', e->>'ref',
        'obs', 'Pago reconstruido el 25/09 con los resúmenes de la tarjeta Visa de Galicia'
               || case when (e->>'dif')::numeric <> 0 then ' (el cupón difiere ' || (e->>'dif') || ' de la factura)' else '' end),
      jsonb_build_array(jsonb_build_object('tipo','factura','factura_id',(e->>'f')::bigint,'monto',(e->>'monto')::numeric)),
      u);
  end loop;
end $m$;
